mapper.select:
select id, machine_name, mix_area, machine_code,have_sulfur_steelyard,have_material_steelyard, remark,status,
mid_status, night_status, day_status, del_flag, create_by, create_time, update_by,
update_time
from t_mix_machine
where del_flag = '0'
and INSTR(machine_name, #{machineName}) > 0
and mix_area = #{mixArea}
and status = #{status}

    order by machine_name


    order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType=VARCHAR} mix_area, #{data.machineCode,jdbcType=VARCHAR} machine_code
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from T_MIX_MACHINE m inner join temp_table t on m.mix_area = t.mix_area and m.machine_code = t.machine_code and m.del_flag ='0'

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType=VARCHAR} mix_area, #{data.machineName,jdbcType=VARCHAR} machine_name
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from T_MIX_MACHINE m inner join temp_table t on m.mix_area = t.mix_area and m.machine_name = t.machine_name and m.del_flag ='0'

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType=VARCHAR} mix_area, #{data.machineName,jdbcType=VARCHAR} machine_name,#{data.machineCode,jdbcType=VARCHAR} machine_code FROM dual
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from T_MIX_MACHINE m inner join temp_table t on m.mix_area = t.mix_area and m.machine_name = t.machine_name and m.machine_code != t.machine_code and m.del_flag ='0'

mapper.insert:
insert into t_mix_machine (id,machine_name,mix_area,machine_code,have_sulfur_steelyard,have_material_steelyard,remark,status,mid_status, night_status, day_status,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{mixMachine.machineName,jdbcType=VARCHAR} machine_name, #{mixMachine.mixArea,jdbcType=VARCHAR} mix_area, #{mixMachine.machineCode,jdbcType=VARCHAR} machine_code, #{mixMachine.haveSulfurSteelyard,jdbcType=VARCHAR} have_sulfur_steelyard, #{mixMachine.haveMaterialSteelyard,jdbcType=VARCHAR} have_material_steelyard, #{mixMachine.remark,jdbcType=VARCHAR} remark, #{mixMachine.status,jdbcType=VARCHAR} status, #{mixMachine.midStatus,jdbcType=VARCHAR} mid_status, #{mixMachine.nightStatus,jdbcType=VARCHAR} night_status, #{mixMachine.dayStatus,jdbcType=VARCHAR} day_status, #{mixMachine.delFlag,jdbcType=VARCHAR} del_flag, #{mixMachine.createBy,jdbcType=VARCHAR} create_by, #{mixMachine.createTime,jdbcType=TIMESTAMP} create_time, #{mixMachine.updateBy,jdbcType=VARCHAR} update_by, #{mixMachine.updateTime,jdbcType=TIMESTAMP} update_time
) x
